namespace DonationHub.Domain.Common;

public enum ErrorType
{
    Validation,          // 400
    Unauthorized,        // 401
    Forbidden,           // 403
    NotFound,            // 404
    Conflict,            // 409
    PayloadTooLarge,     // 413 — لكود File.TooLarge (SRS §6.1)
    UnprocessableEntity, // 422
    TooManyRequests,     // 429
    Failure              // 500
}

public record Error(string Code, string Message, ErrorType Type)
{
    public static readonly Error None = new(string.Empty, string.Empty, ErrorType.Failure);
}

// خطأ تحقق يحمل أخطاء الحقول → يظهر كـ "errors" في ProblemDetails
public sealed record ValidationError(IReadOnlyDictionary<string, string[]> Errors)
    : Error("Validation.Failed", "One or more validation errors occurred.", ErrorType.Validation)
{
    public static ValidationError ForField(string field, string message) =>
        new(new Dictionary<string, string[]> { [field] = [message] });
}

