public static class ErrorTypeExtensions
{
    public static int ToStatusCode(this ErrorType type) => type switch
    {
        ErrorType.Validation => StatusCodes.Status400BadRequest,
        ErrorType.Unauthorized => StatusCodes.Status401Unauthorized,
        ErrorType.Forbidden => StatusCodes.Status403Forbidden,
        ErrorType.NotFound => StatusCodes.Status404NotFound,
        ErrorType.Conflict => StatusCodes.Status409Conflict,
        ErrorType.PayloadTooLarge => StatusCodes.Status413PayloadTooLarge,
        ErrorType.UnprocessableEntity => StatusCodes.Status422UnprocessableEntity,
        ErrorType.TooManyRequests => StatusCodes.Status429TooManyRequests,
        _ => StatusCodes.Status500InternalServerError
    };
}

[ApiController]
public abstract class ApiControllerBase : ControllerBase
{
    // نقطة واحدة تحوّل أي Error إلى RFC 9457 ProblemDetails
    protected IActionResult ProblemFrom(Error error)
    {
        var status = error.Type.ToStatusCode();

        // ProblemDetailsFactory يضيف traceId ويطبّق CustomizeProblemDetails
        var problem = ProblemDetailsFactory.CreateProblemDetails(
            HttpContext, statusCode: status, title: error.Message, type: $"https://httpstatuses.io/{status}");

        problem.Extensions["code"] = error.Code;
        if (error is ValidationError validation)
        {
            problem.Extensions["errors"] = validation.Errors.ToDictionary(
                e => JsonNamingPolicy.CamelCase.ConvertName(e.Key),   // GoalAmount → goalAmount
                e => e.Value);
        }

        return new ObjectResult(problem)
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };
    }
}

