namespace DonationHub.Api.Infrastructure;

internal sealed class GlobalExceptionHandler(
    IProblemDetailsService problemDetailsService,
    ILogger<GlobalExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        // العميل أغلق الاتصال: ليس عطلًا في الخادم، فلا نسجّله كـ Error
        if (exception is OperationCanceledException && httpContext.RequestAborted.IsCancellationRequested)
        {
            logger.LogInformation("Request {Method} {Path} was cancelled by the client.",
                httpContext.Request.Method, httpContext.Request.Path);
            httpContext.Response.StatusCode = 499;   // Client Closed Request (عُرف غير قياسي)
            return true;
        }

        // التفاصيل الكاملة (مع الـ stack trace) في الـ log فقط
        logger.LogError(exception, "Unhandled exception for {Method} {Path}",
            httpContext.Request.Method, httpContext.Request.Path);

        httpContext.Response.StatusCode = StatusCodes.Status500InternalServerError;

        var problem = new ProblemDetails
        {
            Status = StatusCodes.Status500InternalServerError,
            Title = CommonErrors.Unexpected.Message,          // رسالة عامة — لا exception.Message
            Type = "https://httpstatuses.io/500"
        };
        problem.Extensions["code"] = CommonErrors.Unexpected.Code;

        // لا نمرّر Exception إلى السياق حتى لا تظهر تفاصيله بأي إعداد
        return await problemDetailsService.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            ProblemDetails = problem
        });
    }
}

