var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddApplicationServices()
    .AddInfrastructureServices(builder.Configuration);

builder.Services.AddControllers()
    .AddJsonOptions(o => o.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter()));  // "status": "Active"

builder.Services.AddProblemDetails(options =>
    options.CustomizeProblemDetails = context =>
    {
        var extensions = context.ProblemDetails.Extensions;
        extensions.TryAdd("traceId", Activity.Current?.Id ?? context.HttpContext.TraceIdentifier);

        // أخطاء الإطار (JSON غير صالح، 401/403 من الـ middleware) لا تحمل code — نضيف قيمة افتراضية
        extensions.TryAdd("code", context.ProblemDetails.Status switch
        {
            StatusCodes.Status400BadRequest => "Validation.Failed",
            StatusCodes.Status401Unauthorized => "Auth.Unauthorized",
            StatusCodes.Status403Forbidden => "Auth.Forbidden",
            StatusCodes.Status404NotFound => "Common.NotFound",
            _ => "Server.Error"
        });
    });

builder.Services.AddExceptionHandler<GlobalExceptionHandler>();
builder.Services.AddHttpContextAccessor();
builder.Services.AddScoped<ICurrentUser, CurrentUser>();
builder.Services.AddOpenApi(options => options.AddDocumentTransformer<BearerSecuritySchemeTransformer>());

var app = builder.Build();

app.UseExceptionHandler();
app.UseStatusCodePages();      // 401/403/404 بدون جسم → ProblemDetails

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
    app.MapScalarApiReference();
}

app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();

await DbSeeder.SeedAsync(app.Services, app.Environment.IsDevelopment());

app.Run();

