namespace DonationHub.Application.Features.Auth.Login;

public sealed record LoginCommand(string Email, string Password) : IRequest<Result<AuthResponse>>;

public sealed class LoginCommandValidator : AbstractValidator<LoginCommand>
{
    public LoginCommandValidator()
    {
        RuleFor(x => x.Email).NotEmpty().EmailAddress();
        RuleFor(x => x.Password).NotEmpty();      // لا نتحقق من السياسة هنا — لا نكشف شيئًا عن الحساب
    }
}

public sealed class LoginCommandHandler(IIdentityService identity, ITokenService tokens)
    : IRequestHandler<LoginCommand, Result<AuthResponse>>
{
    public async Task<Result<AuthResponse>> Handle(LoginCommand request, CancellationToken ct)
    {
        var user = await identity.FindByEmailAsync(request.Email, ct);

        // IDN-12: نفس الخطأ للبريد غير الموجود ولكلمة المرور الخاطئة
        if (user is null || !await identity.CheckPasswordAsync(user.Id, request.Password))
            return AuthErrors.InvalidCredentials;

        // IDN-10: بعد التحقق من كلمة المرور، حتى لا نكشف وجود الحساب
        if (!user.IsActive)
            return AuthErrors.AccountDeactivated;

        return await tokens.IssueAsync(user, ct);
    }
}

