namespace DonationHub.Application.Features.Auth.Register;

public sealed record RegisterCommand(string Email, string Password, string FullName, string? PreferredLanguage)
    : IRequest<Result<UserAccount>>;

public sealed class RegisterCommandValidator : AbstractValidator<RegisterCommand>
{
    public RegisterCommandValidator()
    {
        RuleFor(x => x.Email).NotEmpty().EmailAddress().MaximumLength(256);
        RuleFor(x => x.FullName).NotEmpty().MaximumLength(150);
        RuleFor(x => x.Password)                                   // IDN-02
            .NotEmpty()
            .MinimumLength(8)
            .Matches("[A-Z]").WithMessage("Password must contain an upper-case letter.")
            .Matches("[a-z]").WithMessage("Password must contain a lower-case letter.")
            .Matches("[0-9]").WithMessage("Password must contain a digit.");
        RuleFor(x => x.PreferredLanguage)
            .Must(l => l is null or "en" or "ar").WithMessage("PreferredLanguage must be 'en' or 'ar'.");
    }
}

public sealed class RegisterCommandHandler(IIdentityService identity)
    : IRequestHandler<RegisterCommand, Result<UserAccount>>
{
    public async Task<Result<UserAccount>> Handle(RegisterCommand request, CancellationToken ct)
    {
        if (await identity.FindByEmailAsync(request.Email, ct) is not null)
            return AuthErrors.EmailAlreadyExists;

        return await identity.CreateUserAsync(request.Email, request.Password, request.FullName.Trim(),
            request.PreferredLanguage ?? "en", Roles.Donor, ct);
    }
}

