namespace DonationHub.Application.Features.Categories.DeleteCategory;

public sealed record DeleteCategoryCommand(Guid Id) : IRequest<Result>;

public sealed class DeleteCategoryCommandHandler(IUnitOfWork uow) : IRequestHandler<DeleteCategoryCommand, Result>
{
    public async Task<Result> Handle(DeleteCategoryCommand request, CancellationToken ct)
    {
        var categories = uow.Repository<Category>();
        var category = await categories.GetByIdAsync(request.Id, ct);
        if (category is null)
            return CategoryErrors.NotFound;

        // CAT-04 / القاعدة 10: الـ handler يجلب الحقيقة، والكيان يقرّر
        var hasCampaigns = await uow.Repository<Campaign>().AnyIncludingDeletedAsync(c => c.CategoryId == request.Id, ct);
        var check = category.EnsureCanBeDeleted(hasCampaigns);
        if (check.IsFailure)
            return check.Error;

        categories.Remove(category);
        await uow.SaveChangesAsync(ct);
        return Result.Success();
    }
}

