namespace DonationHub.Application.Features.Campaigns.UpdateCampaign;

public sealed record UpdateCampaignCommand(
    Guid Id, string TitleAr, string TitleEn, string DescriptionAr, string DescriptionEn,
    decimal GoalAmount, DateTime EndDate, Guid CategoryId, byte[] RowVersion) : IRequest<Result<CampaignAdminResponse>>;

public sealed class UpdateCampaignCommandHandler(IUnitOfWork uow, TimeProvider timeProvider)
    : IRequestHandler<UpdateCampaignCommand, Result<CampaignAdminResponse>>
{
    public async Task<Result<CampaignAdminResponse>> Handle(UpdateCampaignCommand request, CancellationToken ct)
    {
        var campaign = await uow.Repository<Campaign>().GetByIdAsync(request.Id, ct);
        if (campaign is null)
            return CampaignErrors.NotFound;

        if (campaign.CategoryId != request.CategoryId &&
            !await uow.Repository<Category>().AnyAsync(c => c.Id == request.CategoryId, ct))
            return CategoryErrors.NotFound;

        var update = campaign.Update(request.TitleAr, request.TitleEn, request.DescriptionAr, request.DescriptionEn,
            request.GoalAmount, request.EndDate, request.CategoryId, timeProvider.GetUtcNow().UtcDateTime);
        if (update.IsFailure)
            return update.Error;                    // القواعد 2 و 7 و 8 من الكيان نفسه

        uow.SetOriginalRowVersion(campaign, request.RowVersion);   // CMP-10

        try
        {
            await uow.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return CampaignErrors.ConcurrencyConflict;            // 409 — الكاتب الثاني
        }

        return CampaignAdminResponse.From(campaign);              // يحمل RowVersion الجديد
    }
}

