using DonationHub.Domain.Common;

namespace DonationHub.Domain.Campaigns;

public sealed class Campaign : Entity, ISoftDeletable
{
    // ... الخصائص والمُنشئات كما في Sprint 1 (private setters، RowVersion، IsDeleted ...)

    public bool IsFinal => Status is CampaignStatus.Completed or CampaignStatus.Expired;

    public static Result<Campaign> Create(
        string titleAr, string titleEn, string descriptionAr, string descriptionEn,
        decimal goalAmount, DateTime endDate, Guid categoryId, Guid createdByUserId, DateTime utcNow)
    {
        if (goalAmount <= 0) return CampaignErrors.GoalNotPositive;     // القاعدة 1
        if (endDate <= utcNow) return CampaignErrors.EndDateInPast;     // القاعدة 2

        return new Campaign(Guid.NewGuid())
        {
            TitleAr = titleAr.Trim(),
            TitleEn = titleEn.Trim(),
            DescriptionAr = descriptionAr.Trim(),
            DescriptionEn = descriptionEn.Trim(),
            GoalAmount = goalAmount,
            RaisedAmount = 0,
            EndDate = endDate,
            CategoryId = categoryId,
            CreatedByUserId = createdByUserId,
            Status = CampaignStatus.Active,
            CreatedAt = utcNow,
            UpdatedAt = utcNow
        };
    }

    public Result Update(
        string titleAr, string titleEn, string descriptionAr, string descriptionEn,
        decimal goalAmount, DateTime endDate, Guid categoryId, DateTime utcNow)
    {
        // القاعدة 8 — ومعها حملة Active انتهى تاريخها ولم يحوّلها الـ job بعد
        if (IsFinal || EndDate <= utcNow) return CampaignErrors.NotActive;
        if (goalAmount <= 0) return CampaignErrors.GoalNotPositive;
        if (goalAmount < RaisedAmount) return CampaignErrors.GoalBelowRaised;                 // القاعدة 7
        if (endDate != EndDate && endDate <= utcNow) return CampaignErrors.EndDateInPast;     // القاعدة 2

        TitleAr = titleAr.Trim();
        TitleEn = titleEn.Trim();
        DescriptionAr = descriptionAr.Trim();
        DescriptionEn = descriptionEn.Trim();
        GoalAmount = goalAmount;
        EndDate = endDate;
        CategoryId = categoryId;
        UpdatedAt = utcNow;
        return Result.Success();
    }

    // EnsureCanAcceptDonation و ApplySucceededDonation (القاعدة 6) و MarkExpiredIfDue كما هي من Sprint 1؛
    // في Sprint 3 يفحص الـ Handler القاعدتين 3 و 4 أولًا ويُرجع Result، ويبقى DomainException خط دفاع أخير.
}

namespace DonationHub.Domain.Campaigns;

public static class CampaignCalculations
{
    // min(100, raised / goal * 100)
    public static decimal ProgressPercent(decimal raisedAmount, decimal goalAmount) =>
        goalAmount <= 0 ? 0 : Math.Min(100m, Math.Round(raisedAmount / goalAmount * 100m, 2));

    // يوم جزئي متبقٍّ يُحسب يومًا كاملًا، ولا قيمة سالبة أبدًا
    public static int DaysLeft(DateTime endDate, DateTime utcNow)
    {
        var remaining = endDate - utcNow;
        return remaining <= TimeSpan.Zero ? 0 : (int)Math.Ceiling(remaining.TotalDays);
    }
}

namespace DonationHub.Application.Common;

public static class ContentLanguage
{
    public const string English = "en";
    public const string Arabic = "ar";

    // "ar" أو "ar-EG" أو "ar-EG,en;q=0.8" → ar ؛ أي شيء آخر أو غياب الترويسة → en
    public static string FromAcceptLanguage(string? header)
    {
        if (string.IsNullOrWhiteSpace(header))
            return English;

        var first = header.Split(',')[0].Split(';')[0].Trim();
        var primary = first.Split('-')[0];
        return primary.Equals(Arabic, StringComparison.OrdinalIgnoreCase) ? Arabic : English;
    }
}

