namespace DonationHub.Application.Features.Campaigns.GetCampaignById;

public sealed record GetCampaignByIdQuery(Guid Id, string Language) : IRequest<Result<CampaignDetailsResponse>>;

public sealed class GetCampaignByIdQueryHandler(IReadDbContext read, TimeProvider timeProvider)
    : IRequestHandler<GetCampaignByIdQuery, Result<CampaignDetailsResponse>>
{
    public async Task<Result<CampaignDetailsResponse>> Handle(GetCampaignByIdQuery request, CancellationToken ct)
    {
        var isArabic = request.Language == ContentLanguage.Arabic;

        var row = await read.Campaigns                       // الـ query filter يستبعد المحذوف ناعمًا (CMP-03)
            .Where(c => c.Id == request.Id)
            .Select(c => new
            {
                c.Id,
                Title = isArabic ? c.TitleAr : c.TitleEn,
                Description = isArabic ? c.DescriptionAr : c.DescriptionEn,
                c.GoalAmount, c.RaisedAmount, c.EndDate, c.Status, c.CategoryId,
                c.BannerFileName, c.CreatedAt, c.UpdatedAt, c.RowVersion
            })
            .FirstOrDefaultAsync(ct);

        if (row is null)
            return CampaignErrors.NotFound;

        var utcNow = timeProvider.GetUtcNow().UtcDateTime;
        return new CampaignDetailsResponse(
            row.Id, row.Title, row.Description, row.GoalAmount, row.RaisedAmount,
            CampaignCalculations.ProgressPercent(row.RaisedAmount, row.GoalAmount),
            CampaignCalculations.DaysLeft(row.EndDate, utcNow),
            row.EndDate, row.Status, row.CategoryId, row.BannerFileName, row.CreatedAt, row.UpdatedAt, row.RowVersion);
    }
