public sealed record GetActiveCampaignsQuery(string Language) : IRequest<Result<IReadOnlyList<CampaignSummaryResponse>>>;

public sealed class GetActiveCampaignsQueryHandler(IReadDbContext read, TimeProvider timeProvider)
    : IRequestHandler<GetActiveCampaignsQuery, Result<IReadOnlyList<CampaignSummaryResponse>>>
{
    public async Task<Result<IReadOnlyList<CampaignSummaryResponse>>> Handle(GetActiveCampaignsQuery request, CancellationToken ct)
    {
        var isArabic = request.Language == ContentLanguage.Arabic;
        var utcNow = timeProvider.GetUtcNow().UtcDateTime;

        var rows = await read.Campaigns
            .Where(c => c.Status == CampaignStatus.Active && c.EndDate > utcNow)
            .OrderBy(c => c.EndDate)                         // الأقرب انتهاءً أولًا
            .Select(c => new
            {
                c.Id,
                Title = isArabic ? c.TitleAr : c.TitleEn,
                Description = isArabic ? c.DescriptionAr : c.DescriptionEn,
                c.GoalAmount, c.RaisedAmount, c.EndDate, c.Status, c.CategoryId
            })
            .ToListAsync(ct);

        IReadOnlyList<CampaignSummaryResponse> items = rows
            .Select(r => new CampaignSummaryResponse(
                r.Id, r.Title, r.Description, r.GoalAmount, r.RaisedAmount,
                CampaignCalculations.ProgressPercent(r.RaisedAmount, r.GoalAmount),
                CampaignCalculations.DaysLeft(r.EndDate, utcNow),
                r.EndDate, r.Status, r.CategoryId))
            .ToList();

        return Result<IReadOnlyList<CampaignSummaryResponse>>.Success(items);   // T واجهة → Success صراحةً
