using Microsoft.Extensions.Time.Testing;

namespace DonationHub.UnitTests.Domain;

public class CampaignTests
{
    private static readonly DateTime Now = new(2026, 11, 10, 12, 0, 0, DateTimeKind.Utc);

    private static Campaign NewCampaign(decimal goal = 1_000m, int daysToEnd = 30) =>
        Campaign.Create("حملة", "Campaign", "وصف", "Description", goal,
            Now.AddDays(daysToEnd), Guid.NewGuid(), Guid.NewGuid(), Now).Value;

    [Theory]
    [InlineData(0)]
    [InlineData(-50)]
    public void Create_WithNonPositiveGoal_ReturnsValidationFailed(int goal)   // InlineData لا يقبل decimal
    {
        var result = Campaign.Create("حملة", "Campaign", "وصف", "Description", (decimal)goal,
            Now.AddDays(10), Guid.NewGuid(), Guid.NewGuid(), Now);

        result.IsFailure.Should().BeTrue();
        result.Error.Code.Should().Be("Validation.Failed");
    }

    [Fact]
    public void Create_WithEndDateInPast_ReturnsEndDateInPast()
    {
        var time = new FakeTimeProvider(new DateTimeOffset(Now));
        var utcNow = time.GetUtcNow().UtcDateTime;

        var result = Campaign.Create("حملة", "Campaign", "وصف", "Description", 500m,
            utcNow.AddMinutes(-1), Guid.NewGuid(), Guid.NewGuid(), utcNow);

        result.Error.Should().Be(CampaignErrors.EndDateInPast);
    }

    [Fact]
    public void Update_GoalBelowRaised_ReturnsGoalBelowRaised()
    {
        var campaign = NewCampaign(goal: 1_000m);
        var donation = Donation.Create(campaign, Guid.NewGuid(), 600m, 1m, 10_000m, Now);
        donation.MarkSucceeded(campaign, "DN-2026-000001", Now);

        var result = campaign.Update("حملة", "Campaign", "وصف", "Description",
            500m, campaign.EndDate, campaign.CategoryId, Now);

        result.Error.Should().Be(CampaignErrors.GoalBelowRaised);
        campaign.GoalAmount.Should().Be(1_000m);           // لم يتغيّر شيء
    }

    [Fact]
    public void Update_WhenCampaignExpired_ReturnsNotActive()
    {
        var campaign = NewCampaign(daysToEnd: 1);
        var later = Now.AddDays(2);
        campaign.MarkExpiredIfDue(later);

        var result = campaign.Update("حملة", "Campaign", "وصف", "Description",
            2_000m, later.AddDays(30), campaign.CategoryId, later);

        campaign.Status.Should().Be(CampaignStatus.Expired);
        result.Error.Should().Be(CampaignErrors.NotActive);
    }

    [Fact]
    public void SucceededDonation_ReachingGoal_CompletesCampaign()
    {
        var campaign = NewCampaign(goal: 100m);
        var donation = Donation.Create(campaign, Guid.NewGuid(), 100m, 1m, 10_000m, Now);

        donation.MarkSucceeded(campaign, "DN-2026-000002", Now);

        campaign.Status.Should().Be(CampaignStatus.Completed);
        campaign.RaisedAmount.Should().Be(100m);
    }

    [Theory]
    [InlineData(250, 1000, 25)]
    [InlineData(1500, 1000, 100)]          // مسقوف عند 100
    public void ProgressPercent_IsCappedAt100(int raised, int goal, int expected) =>
        CampaignCalculations.ProgressPercent(raised, goal).Should().Be(expected);

    [Fact]
    public void DaysLeft_FollowsTimeProvider_AndNeverGoesNegative()
    {
        var time = new FakeTimeProvider(new DateTimeOffset(Now));
        var endDate = Now.AddDays(10);

        CampaignCalculations.DaysLeft(endDate, time.GetUtcNow().UtcDateTime).Should().Be(10);

        time.Advance(TimeSpan.FromDays(9.5));
        CampaignCalculations.DaysLeft(endDate, time.GetUtcNow().UtcDateTime).Should().Be(1);

        time.Advance(TimeSpan.FromDays(5));
        CampaignCalculations.DaysLeft(endDate, time.GetUtcNow().UtcDateTime).Should().Be(0);
    }
}

