    [Fact]
    public async Task ValidationBehavior_WhenInvalid_ShortCircuits_WithoutCallingHandler()
    {
        var behavior = new ValidationBehavior<CreateCampaignCommand, Result<CampaignAdminResponse>>(
            [new CreateCampaignCommandValidator()]);
        var handlerCalled = false;
        RequestHandlerDelegate<Result<CampaignAdminResponse>> next = _ =>
        {
            handlerCalled = true;
            return Task.FromResult<Result<CampaignAdminResponse>>(CampaignErrors.NotFound);
        };

        var result = await behavior.Handle(Valid with { TitleEn = "" }, next, CancellationToken.None);

        handlerCalled.Should().BeFalse();
        result.Error.Code.Should().Be("Validation.Failed");
