public Result Cancel(DateTime utcNow)
{
    if (IsFinal) return CampaignErrors.NotActive;     // IsFinal يشمل Cancelled الآن
    Status = CampaignStatus.Cancelled;
    UpdatedAt = utcNow;
    return Result.Success();
}

public abstract class Specification<T>
{
    public abstract Expression<Func<T, bool>> ToExpression();
}

public sealed class ActiveCampaignsSpec(DateTime utcNow) : Specification<Campaign>
{
    public override Expression<Func<Campaign, bool>> ToExpression() =>
        c => c.Status == CampaignStatus.Active && c.EndDate > utcNow;
}

